import sys; sys.path.insert(0,'/tmp/ss-build/tools/c10')
from lib10 import *
S='social-science'
def B(ch,cn,t,tn,*a,**k): build(S,ch,t,tn,*a,cname=cn,tname=tn,**k)
R="Both A and R are true and R explains A"
C,CN='civ-power-sharing','Political Science 1: Power Sharing'
B(C,CN,'power-sharing','Power Sharing',
 "Two countries, two answers",
 "Belgium and Sri Lanka both have people who speak different languages. One shared power and stayed together; the other did not, and went through a long civil conflict. Today we learn why.",
 [("In Belgium about 59 per cent of people live in the Dutch-speaking region and about 40 per cent in the French-speaking region, with a small German-speaking community. Brussels is a mixed capital.","Belgium"),
  ("The Belgians changed the Constitution to share power: equal Dutch and French ministers in the central government, state governments with powers of their own, and a separate Community Government for each language group.","Belgian model"),
  ("In Sri Lanka, Sinhala-speakers are about 74 per cent and Tamil-speakers about 18 per cent. In 1956 an Act made Sinhala the only official language.","Sri Lanka"),
  ("The majoritarian measures made Tamils feel alienated, and the conflict grew into a civil war.","majoritarianism"),
  ("Power sharing is good because it reduces conflict between groups and is the very spirit of democracy, as it gives people a say.","why power sharing"),
  ("Forms of power sharing include horizontal sharing among legislature, executive and judiciary, vertical sharing among levels of government, sharing among social groups, and sharing among parties and movements.","four forms"),
  ("Horizontal sharing is also called a system of checks and balances.","checks and balances"),
  ("Community government in Belgium and reserved constituencies in India are examples of sharing power among social groups.","examples")],
 ("In Belgium 59 per cent speak Dutch and 40 per cent French. What per cent is left?",[("Add the two shares: 59 + 40 = 99.","Together they cover 99 per cent."),("100 - 99 = 1 per cent, the German-speaking community.","This matches the text.")]),
 ("Explain why power sharing is desirable.",["Reduces conflict","Respects diversity","Is the spirit of democracy"],["Thinking majority rule means no sharing"]),
 ["Belgium shared power and Sri Lanka did not.","Majoritarianism creates alienation.","There are four forms of power sharing.","Power sharing is the spirit of democracy."],
 [mcq("p1-1",1,"Which language became the only official language in Sri Lanka by the Act of 1956?","Sinhala",[("Tamil","Tamil was neglected."),("English","Not the Act's language.")],"It alienated Tamils."),
  tf("p1-2",1,"Belgium has a Community Government for each language group.",True,"This is part of its power-sharing model."),
  mcq("p1-3",2,"Horizontal power sharing means","power is shared among different organs of government",[("power shared between Centre and states","That is vertical."),("power shared by parties","That is another form.")],"It is checks and balances."),
  mcq("p1-4",2,"Assertion (A): Power sharing reduces the possibility of conflict. Reason (R): It respects different groups.",R,[("A true, R false","R is true."),("Both false","Both correct.")],"Sharing builds trust."),
  short("p1-5",2,"What is the capital of Belgium?",["brussels"],"Brussels has a mixed population.",[("antwerp","Not the capital.")]),
  mcq("p1-6",3,"Power sharing between Union and states is called","vertical division",[("horizontal division","Among organs of government."),("coalition","Among parties.")],"Federalism is an example."),
  tf("p1-7",3,"Majoritarianism always builds national unity.",False,"It can alienate minorities."),
  num("p1-8",3,"How many forms of power sharing does the chapter list?",4,"Horizontal, vertical, among groups and among parties.",[(3,"There are four.")])])
C,CN='civ-federalism','Political Science 2: Federalism'
B(C,CN,'federalism','Federalism',
 "Who looks after the roads and who the army?",
 "Your village road is looked after by a local body, the state handles police, and the Union runs the army. Why is power split? That is federalism.",
 [("Federalism is a system of government in which power is divided between a central authority and the various units of the country, each with its own powers.","federalism"),
  ("A federation has two levels of government that govern the same citizens and have separate jurisdiction, and the Constitution cannot be changed by one level alone.","key features"),
  ("The Constitution lists subjects in three lists. The Union List includes defence and foreign affairs, the State List includes police and agriculture, and the Concurrent List includes education and marriage. Residuary subjects go to the Union.","three lists"),
  ("India is described as a 'union of states', and the Parliament can form new states and alter boundaries.","union of states"),
  ("India does not have a national language. Hindi is the official language, and the Constitution recognises 22 scheduled languages.","language policy"),
  ("Linguistic states were created from the 1950s so that each state would have its own language and culture.","linguistic states"),
  ("A major step towards decentralisation was taken in 1992, when the Constitution was amended to make the third tier of government, local self-government, more powerful.","1992 amendment"),
  ("Panchayati Raj has the gram sabha, gram panchayat, block and zilla parishad levels. At least one-third of positions are reserved for women.","Panchayati Raj")],
 ("A panchayat has 12 seats and one-third are reserved for women. How many seats?",[("Take one-third of 12.","12 / 3."),("12 / 3 = 4 seats.","The rest are 8 general seats.")]),
 ("Explain how power is shared in India's federation.",["Union, State and Concurrent Lists","Local governments","Constitution safeguards division"],["Thinking states have no powers"]),
 ["Federalism divides power between levels.","India has three lists of subjects.","Language policy is flexible.","Local government was strengthened in 1992."],
 [mcq("p2-1",1,"Defence belongs to the","Union List",[("State List","Police and agriculture."),("Concurrent List","Education.")],"Only the Union legislates on it."),
  tf("p2-2",1,"India has a single national language.",False,"Hindi is official; there is no national language."),
  mcq("p2-3",2,"The third tier of government is","local government",[("high court","Not a tier."),("cabinet","Not a tier.")],"Panchayats and municipalities."),
  mcq("p2-4",2,"Assertion (A): Decentralisation is good. Reason (R): Local issues are best settled locally.",R,[("A true, R false","R explains A."),("Both false","Both correct.")],"People know local needs."),
  short("p2-5",2,"Which list includes education?",["concurrent","concurrent list"],"Both Union and states can legislate.",[("union","Union List has defence.")]),
  num("p2-6",2,"Year of the amendment that strengthened local government",1992,"The 73rd and 74th amendments.",[(1950,"Constitution year.")]),
  mcq("p2-7",3,"Which body consists of all voters in a village?","Gram Sabha",[("Zilla Parishad","District level."),("Lok Sabha","National.")],"It is the basic body."),
  tf("p2-8",3,"At least one-third of panchayat positions are reserved for women.",True,"Reservation helps women participate.")])
C,CN='civ-gender-religion-and-caste','Political Science 3: Gender, Religion and Caste'
B(C,CN,'gender-religion-and-caste','Gender, Religion and Caste',
 "Do differences divide or enrich politics?",
 "In your class, children differ in gender, religion and caste. How should politics deal with these differences? This chapter looks at how they shape and are shaped by politics.",
 [("Sexual division of labour means household work is done mostly by women while men do paid work outside, though both can do either. This is a social role, not natural.","sexual division of labour"),
  ("Women's movements demanded equal rights, the vote and equal pay. Women's representation in legislatures is still low in India.","women's movements"),
  ("The Equal Remuneration Act 1976 says equal wages for equal work for men and women.","Equal wages"),
  ("Reservation of one-third of seats for women in local bodies has increased their presence. A demand continues for similar reservation in legislatures.","reservation"),
  ("Communalism means treating religion as the basis of the community and politics. It is a problem when religion is mixed with state power.","communalism"),
  ("India is a secular state, which means no official religion and equal freedom for all faiths.","secularism"),
  ("Caste has played a role in politics through caste groups, alliances and voting. But caste cannot decide every election, as people vote on other issues too.","caste and politics"),
  ("Caste inequalities are slowly changing through education, urbanisation and law, but discrimination still exists.","changing caste")],
 ("A legislature has 150 seats. If one-third were reserved for women, how many seats?",[("One-third of 150.","150 / 3."),("= 50 seats.","Today the share is lower in many legislatures.")]),
 ("Explain why communalism is dangerous in politics.",["Uses religion to gain power","Divides citizens","Secularism protects equality"],["Thinking religion has no place in life"]),
 ["Gender roles are socially created.","India is a secular state.","Communalism harms unity.","Caste influences but does not decide politics."],
 [mcq("p3-1",1,"A secular state","has no official religion",[("has one state religion","That is the opposite."),("bans all religions","It protects freedom of religion.")],"All faiths are equal."),
  tf("p3-2",1,"Sexual division of labour is natural, not social.",False,"It is created by society."),
  mcq("p3-3",2,"The Equal Remuneration Act 1976 provides","equal wages for equal work",[("free education","Different law."),("land rights","Different law.")],"For men and women."),
  mcq("p3-4",2,"Assertion (A): Communalism is a threat to democracy. Reason (R): It uses religion to divide people.",R,[("A true, R false","R is true."),("Both false","Both correct.")],"It harms unity."),
  short("p3-5",2,"What do we call treating religion as the basis of community in politics?",["communalism"],"It is the opposite of secularism.",[("secularism","That is equal respect.")]),
  tf("p3-6",3,"Caste alone decides every election result.",False,"Voters consider many issues."),
  mcq("p3-7",3,"Which tool increased women's presence in local bodies?","Reservation of one-third seats",[("Banning elections","No."),("Free travel","No.")],"Panchayats reserve seats."),
  tf("p3-8",3,"Reserving seats for women in local bodies has increased their participation.",True,"One-third reservation brought many women into panchayats.")])
C,CN='civ-political-parties','Political Science 4: Political Parties'
B(C,CN,'political-parties','Political Parties',
 "Who runs for the school election?",
 "Every election needs groups of people who agree on how to run things. Political parties do that job in a democracy. Let us see their functions and challenges.",
 [("A political party is a group of people who come together to contest elections and hold power in government. They agree on policies for the good of society.","political party"),
  ("Parties contest elections, put forward policies and programmes, make laws, form and run governments, play the role of opposition, shape public opinion and run welfare schemes.","functions"),
  ("A party has leaders, active members and followers. Parties are necessary because democracy needs representation and competition.","components"),
  ("In a one-party, two-party or multi-party system, the number of parties vary. India has a multi-party system with alliances.","party systems"),
  ("The Election Commission registers parties and recognises national parties. A national party must get at least six per cent of total votes in four states and win at least four seats in the Lok Sabha.","national party rule"),
  ("Parties face challenges like lack of internal democracy, dynastic succession, money and muscle power, and meaningless choices.","challenges"),
  ("Anti-defection law and mandatory disclosure of assets and criminal cases are some reforms. Citizens can also pressure parties.","reforms"),
  ("Voters are the real power. Informed voting and participation help keep parties accountable.","voters")],
 ("A party got 20 lakh votes out of 200 lakh total. What percent?",[("Divide party votes by total.","20 / 200."),("= 0.1 = 10 per cent.","Compare with the 6 per cent rule.")]),
 ("List the functions of political parties.",["Contest elections","Form governments and opposition","Shape public opinion and run schemes"],["Thinking parties only fight elections"]),
 ["Parties contest elections and govern.","India has a multi-party system.","Parties face challenges.","Reforms and voters keep them accountable."],
 [mcq("p4-1",1,"Which body recognises a national party in India?","Election Commission",[("Supreme Court","Not responsible."),("Parliament","Not responsible.")],"It registers and recognises parties."),
  tf("p4-2",1,"India has a multi-party system.",True,"Many parties and alliances."),
  mcq("p4-3",2,"A national party needs at least what share of votes in four states?","6 per cent",[("1 per cent","Too low."),("25 per cent","Too high.")],"Along with four Lok Sabha seats."),
  mcq("p4-4",2,"Assertion (A): Parties are necessary in a democracy. Reason (R): They organise elections and form governments.",R,[("A true, R false","R explains A."),("Both false","Both correct.")],"They make representation workable."),
  short("p4-5",2,"What do we call a party that is not in government?",["opposition","the opposition"],"It criticises and checks the government.",[("ruling","The ruling party governs.")]),
  mcq("p4-6",3,"A challenge before parties is","lack of internal democracy",[("too much transparency","Not a challenge."),("free elections","A feature, not a challenge.")],"Power is concentrated in a few leaders."),
  tf("p4-7",3,"The anti-defection law was meant to stop MLAs from changing parties for gain.",True,"It aims to give stability."),
  num("p4-8",3,"Minimum Lok Sabha seats a national party must win",4,"Along with at least six per cent of votes in four states.",[(2,"The textbook rule says four.")])])
C,CN='civ-outcomes-of-democracy','Political Science 5: Outcomes of Democracy'
B(C,CN,'outcomes-of-democracy','Outcomes of Democracy',
 "Does democracy deliver?",
 "People expect democracy to give them better lives. Does it? This chapter looks at what democracy can and cannot deliver.",
 [("We judge democracy by its outcomes: accountable, responsive and legitimate government, economic growth and development, reduction of inequality and poverty, accommodation of social diversity and dignity and freedom of citizens.","what to judge"),
  ("A democratic government is accountable, because people can question it and change it through elections. It is also responsive to the needs of people.","accountable and responsive"),
  ("Democracy is legitimate because it is people's own government. A slower decision-making process is the price of consultation.","legitimate"),
  ("On economic growth, dictatorships have sometimes grown faster, but on average the difference is small. Democracies can do better on equality.","economic growth"),
  ("Democracy has not removed poverty or inequality fully, as many are still poor. So we must make democracy work for them.","inequality"),
  ("A democratic government accommodates social differences by respecting diversity and avoiding conflicts, as Belgium shows.","social diversity"),
  ("Democracy enhances the dignity and freedom of the individual, giving equal respect and the right to vote.","dignity and freedom"),
  ("Democracy is better because it allows correction of mistakes. People's expectations create demands that make democracy deeper.","correcting mistakes")],
 ("A democracy and a dictatorship grow at 4 and 4.5 per cent. By how much do they differ?",[("Subtract the smaller from larger.","4.5 - 4."),("= 0.5 percentage points.","The gap is small.")]),
 ("Explain why democracy is considered better than other forms.",["Accountable and legitimate","Respects dignity and freedom","Allows correction of mistakes"],["Thinking democracy gives quick growth always"]),
 ["Democracy's outcomes include accountability, legitimacy and dignity.","Economic growth difference is small.","Inequality needs continued effort.","Democracy accommodates diversity."],
 [mcq("p5-1",1,"A government that people can question and replace is","accountable",[("secretive","Opposite."),("unelected","Not defined.")],"People hold it answerable."),
  tf("p5-2",1,"Democracy has completely removed inequality.",False,"Inequality persists."),
  mcq("p5-3",2,"Democracy is legitimate because it is","the people's own government",[("always the fastest","It can be slow."),("rich","Unrelated.")],"People accept it as their own."),
  mcq("p5-4",2,"Assertion (A): Democracy can correct its own mistakes. Reason (R): People can change governments.",R,[("A true, R false","R is correct."),("Both false","Both correct.")],"Elections allow correction."),
  short("p5-5",2,"Which value does democracy enhance for every individual?",["dignity","dignity and freedom","freedom"],"It treats all as equal.",[("wealth","It does not promise equal wealth.")]),
  tf("p5-6",3,"Dictatorships always grow faster than democracies.",False,"The difference is small on average."),
  mcq("p5-7",3,"Democracy accommodates social diversity by","respecting differences and avoiding conflict",[("banning minorities","Not democratic."),("ignoring languages","Not accommodating.")],"Belgium's example."),
  tf("p5-8",3,"Democracy treats all citizens as equal in voting.",True,"Each adult has one vote of equal value.")])
